document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="tablet.css"><link rel="stylesheet" href="homeaway.css">');
const q=new URLSearchParams(location.search),a=q.get('a')||'FLA',b=q.get('b')||'WPG',ta=teams[a],tb=teams[b],root=document.querySelector('#nhl-content');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function load(){try{const d=await fetch('nhl-data.json').then(r=>r.json());render(d.standings[a],d.standings[b],d.meetings[`${a}-${b}`]||[],d.updatedAt)}catch{root.innerHTML='<div class="nhl-error"><h1>Kunde inte hämta NHL-data</h1><p>Försök igen om en liten stund.</p></div>'}}
function logo(code){return `https://assets.nhle.com/logos/nhl/svg/${code}_light.svg`}
function standRow(code,t,s){return `<div class="stand-row"><img src="${logo(code)}" alt=""><div><b>${esc(t.name)}</b><span>${s?`${s.wins}–${s.losses}–${s.otLosses} · ${s.points} poäng`:'Uppgift saknas'}</span></div><strong>${s?`#${s.leagueSequence}`:'–'}</strong></div>`}
function gameRow(g){const x=g.awayTeam,y=g.homeTeam;return `<div class="meeting-row"><time>${new Date(g.gameDate+'T12:00:00').toLocaleDateString('sv-SE',{day:'numeric',month:'short',year:'numeric'})}</time><div><span>${esc(x.placeName||x.abbrev)}</span><b>${x.score} – ${y.score}</b><span>${esc(y.placeName||y.abbrev)}</span></div><small>${esc(g.venue||'')}</small></div>`}
function render(sa,sb,games,updatedAt){if(!ta||!tb){root.innerHTML='<p>Lagparet hittades inte. Välj en match från dagens lista.</p>';return}const asOf=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',day:'numeric',month:'long',year:'numeric'}).format(new Date(updatedAt));root.innerHTML=`<section class="match-hero"><p class="eyebrow">NHL · MATCHFAKTA</p><div class="matchup"><div class="club"><span class="club-label">HEMMALAG</span><img src="${logo(a)}" alt=""><h1>${ta.name}</h1><p>${ta.city}</p></div><div class="versus"><span>MOT</span><i></i></div><div class="club"><span class="club-label">BORTALAG</span><img src="${logo(b)}" alt=""><h1>${tb.name}</h1><p>${tb.city}</p></div></div><p class="venue-line"><span>HEMMAARENA</span><b>${ta.arena} · ${ta.city}</b></p><p class="data-note"><span class="pulse"></span> Verifierad ögonblicksbild från NHL · ${esc(asOf)}</p></section><section class="nhl-grid"><article class="nhl-card"><p class="eyebrow dark">TABELL VID KONTROLL ${esc(asOf.toLocaleUpperCase('sv-SE'))}</p><h2>Ligaplacering</h2>${standRow(a,ta,sa)}${standRow(b,tb,sb)}<a href="https://www.nhl.com/standings/" target="_blank">Se hela NHL-tabellen ↗</a></article><article class="nhl-card"><p class="eyebrow dark">SENASTE MÖTENA</p><h2>Inbördes matcher</h2>${games.length?games.map(gameRow).join(''):'<p>Inga avslutade möten hittades.</p>'}</article></section><section class="map-section"><div><p class="eyebrow">VAR LAGEN FINNS</p><h2>Två lag.<br>En kontinent.</h2><div class="map-legend"><p><b>${ta.city}</b><span>${ta.arena}</span></p><p><b>${tb.city}</b><span>${tb.arena}</span></p></div></div><div id="nhl-map" class="nhl-real-map"></div></section>`;if(typeof L!=='undefined')initMap()}
function initMap(){const map=L.map('nhl-map',{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap'}).addTo(map);const makeIcon=(color,code)=>L.divIcon({className:'team-map-icon',html:`<span style="--pin:${color}">${code}</span>`,iconSize:[50,50],iconAnchor:[25,25]});const m1=L.marker([ta.lat,ta.lon],{icon:makeIcon('#ff5b35',a)}).addTo(map).bindPopup(`<b>${ta.name}</b><br>${ta.arena}<br>${ta.city}`),m2=L.marker([tb.lat,tb.lon],{icon:makeIcon('#b9ffcf',b)}).addTo(map).bindPopup(`<b>${tb.name}</b><br>${tb.arena}<br>${tb.city}`);L.polyline([[ta.lat,ta.lon],[tb.lat,tb.lon]],{color:'#0d6b50',weight:3,dashArray:'9 10'}).addTo(map);map.fitBounds(L.latLngBounds([m1.getLatLng(),m2.getLatLng()]).pad(.35),{maxZoom:6});setTimeout(()=>map.invalidateSize(),80)}load();
